import itertools

def is_costas(p):
    n = len(p)
    vectors = set()
    for i in range(n):
        for j in range(i + 1, n):
            vector = (j - i, p[j] - p[i])
            if vector in vectors:
                return False
            vectors.add(vector)
    return True

def find_costas(n):
    for p in itertools.permutations(range(n)):
        if is_costas(p):
            return p
    return None

print(find_costas(8))
